insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0005-0000-4000-8000-00000000001e', 'en', null, 'Women''s History: A Global Survey', 'A global survey of women''s history, from the ancient world to the present, tracing the lives, rulers, and movements that standard histories long left out. It covers why and how women''s history is studied, the suffrage campaigns and the waves of feminism, and women''s achievements in science and the arts. Structure and facts adapted from Wikipedia, the free encyclopedia (CC BY-SA 4.0).', null, 'foundations', 76, true, 'humanities', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0005-0000-4000-8000-00000000001e', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The first author in world history whose name is attached to her own writing was...","options":["Sappho of Lesbos","Enheduanna of Akkad","Hypatia of Alexandria","Ban Zhao"],"answer":1,"explanation":"Enheduanna, a priestess in Mesopotamia around 2300 BCE, is the earliest author known by name - see ''The ancient and classical world''."},{"prompt":"The 1848 Seneca Falls Convention is best known for...","options":["granting women the vote","the Declaration of Sentiments demanding women''s rights","founding the first women''s college","ending married women''s property restrictions"],"answer":1,"explanation":"The convention issued the Declaration of Sentiments, which called for women''s equality, including the vote."},{"prompt":"The first self-governing country to grant women the national vote was...","options":["the United States","the United Kingdom","New Zealand","Switzerland"],"answer":2,"explanation":"New Zealand enfranchised women in 1893, decades ahead of most of the world."},{"prompt":"The 1949 book ''The Second Sex,'' a landmark of feminist thought, was written by...","options":["Betty Friedan","Simone de Beauvoir","Rebecca Walker","Gerda Lerner"],"answer":1,"explanation":"Simone de Beauvoir''s ''The Second Sex'' helped shape later feminist movements."},{"prompt":"The only woman to rule China as emperor in her own right was...","options":["Wu Zetian","Empress Dowager Cixi","Ban Zhao","Murasaki Shikibu"],"answer":0,"explanation":"Wu Zetian reigned as emperor from 690 to 705 - see ''The medieval world across cultures''."},{"prompt":"How many Nobel Prizes in the sciences did Marie Curie win?","options":["one","two","three","none; she was overlooked"],"answer":1,"explanation":"Curie won the Physics prize in 1903 and the Chemistry prize in 1911, the only person to win in two sciences."},{"prompt":"The 1405 book ''The Book of the City of Ladies,'' a defense of women, was written by...","options":["Hildegard of Bingen","Christine de Pizan","Eleanor of Aquitaine","Murasaki Shikibu"],"answer":1,"explanation":"Christine de Pizan was among the first European women to earn a living by writing."},{"prompt":"Ada Lovelace is remembered today as...","options":["the first woman to earn a medical degree","an early computer programmer","a suffragette leader","a Renaissance painter"],"answer":1,"explanation":"Her 1840s notes on Babbage''s Analytical Engine are often called the first computer program."}]}'::jsonb, null, 10),
  (2, 'Why we study women''s history', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why women''s history grew into a field of study, and name the methods historians use to recover lives the records left out. Warm-up: if most surviving documents were written by men, what kinds of sources might still reveal women''s experience?"},{"heading":"The idea","text":"For most of recorded history, the people who wrote chronicles, laws, and official records were overwhelmingly men, so women appear rarely and often only through others'' words. Women''s history, which grew into a formal field in the 1960s and 1970s, asks what that gap hides and how to fill it. Historians read familiar sources ''against the grain,'' hunting for women in the margins of tax rolls, court cases, parish registers, and household accounts. They also turn to letters, diaries, wills, embroidery, cookbooks, and oral testimony. The goal is not only to add forgotten names to an old story but to ask whether the story itself was framed around men. Gerda Lerner, who helped build the first graduate programs in the subject, argued that recovering women was only the first step; the harder task was rethinking how history is organized, which periods count as progress, and for whom."},{"heading":"Key events & figures","text":"The word ''herstory'' spread in the early 1970s as a playful challenge to a male-centered past. Gerda Lerner (1920 to 2013) built some of the earliest degree programs in women''s history in the United States. Joan Kelly''s 1977 essay ''Did Women Have a Renaissance?'' showed that a period long celebrated as an age of progress could look very different from women''s vantage. International Women''s Day, first marked in 1911, became a United Nations observance in 1977. Women''s History Month in the United States grew from a local week in 1978 into a national month by 1987. Together these mark the subject''s move from the edges of scholarship into the mainstream."},{"heading":"Your turn","text":"1) Why do women appear less often in old written records? 2) Name two everyday sources that can reveal women''s lives. 3) What does reading a document ''against the grain'' mean? 4) Who argued that recovery was only the first step? 5) In what year was International Women''s Day first marked? Answers: 1) Because the official record-keepers were mostly men. 2) Letters and household accounts (wills, diaries, and court records also work). 3) Reading a source for what it reveals indirectly about people it was not written about. 4) Gerda Lerner. 5) 1911."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming that if women are absent from the record, they were absent from the event. Mistake: treating women''s history as one global story rather than many, differing by place, class, and race. Exit: (a) Name one method historians use to recover hidden lives. (b) Who wrote ''Did Women Have a Renaissance?'' Answers: reading sources against the grain (or using letters, court records, and oral history); Joan Kelly."}]}'::jsonb, 'A silence in the record is itself evidence - always ask who kept the sources and whose lives they left out.', 12),
  (3, 'The ancient and classical world', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Identify women who shaped the ancient and classical world across Mesopotamia, Egypt, Greece, Rome, and China. Warm-up: who do you think is the first author in history known by name?"},{"heading":"The idea","text":"Even where law and custom limited women''s public power, individual women left marks that survive. In Mesopotamia around 2300 BCE, the priestess Enheduanna of Akkad composed temple hymns and is the first author in world history whose name is attached to her work. Egyptian women could own property and bring cases to court, and Hatshepsut ruled as pharaoh in her own right. In classical Greece, where citizen women were largely confined to the household, the poet Sappho of Lesbos became one of the most admired voices in the language. Rome gave elite women influence through family wealth and property, though not the vote or public office. In Han China, the scholar Ban Zhao completed an official dynastic history and wrote on women''s conduct. These lives show that absence from the political center did not mean absence from culture or learning."},{"heading":"Key events & figures","text":"Enheduanna (around 2300 BCE), daughter of Sargon of Akkad, wrote hymns still studied today. Hatshepsut reigned as pharaoh around 1479 to 1458 BCE. Sappho (around 600 BCE) wrote lyric poetry on the island of Lesbos. In Han China, Ban Zhao (around 45 to 116 CE) helped finish the ''Book of Han.'' Cleopatra VII (69 to 30 BCE) was the last ruler of Ptolemaic Egypt and descended from a Greek, not Egyptian, line. Hypatia of Alexandria (around 355 to 415 CE) taught mathematics, astronomy, and philosophy before she was killed by a mob, a death later taken as a symbol of learning under threat."},{"heading":"Your turn","text":"1) Who is the first named author in history? 2) Which woman ruled Egypt as pharaoh centuries before Cleopatra? 3) Where did Sappho live? 4) What did Ban Zhao help write? 5) What subjects did Hypatia teach? Answers: 1) Enheduanna of Akkad. 2) Hatshepsut. 3) The island of Lesbos. 4) The ''Book of Han,'' an official dynastic history. 5) Mathematics, astronomy, and philosophy."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming Cleopatra was Egyptian by descent; she came from the Greek Ptolemaic line that ruled Egypt. Mistake: thinking no women held any public power in antiquity. Exit: (a) Name the first author known by name. (b) In roughly what year did Hypatia die? Answers: Enheduanna; around 415 CE."}]}'::jsonb, 'Dates before the common era (BCE) count backward, so 2300 BCE is older than 600 BCE.', 13),
  (4, 'The medieval world across cultures', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compare the roles and achievements of women across medieval Europe, East Asia, the Islamic world, and South Asia. Warm-up: can you name a novel written by a woman a thousand years ago?"},{"heading":"The idea","text":"The long span often called medieval was not a single experience for women; it differed sharply by region, religion, and rank. In Japan around 1008, the court attendant Murasaki Shikibu wrote ''The Tale of Genji,'' frequently called the world''s first novel. In China, Wu Zetian became the only woman to rule as emperor in her own right. In the German Rhineland, the abbess Hildegard of Bingen composed music, wrote on medicine and the natural world, and advised popes and kings. In Delhi, Razia Sultana governed a major Muslim state. Across the Islamic world, women endowed learning and charity; Fatima al-Fihri is traditionally credited with founding one of the oldest continuously operating universities. Seen together, these lives caution against treating the period as uniformly bleak for women everywhere."},{"heading":"Key events & figures","text":"Murasaki Shikibu wrote ''The Tale of Genji'' in early eleventh-century Japan. Wu Zetian (624 to 705) reigned as emperor of China from 690 to 705. Hildegard of Bingen (1098 to 1179) led a German convent and left music and natural writings. Fatima al-Fihri is traditionally said to have founded the University of al-Qarawiyyin in Fez in 859. Razia Sultana ruled the Delhi Sultanate from 1236 to 1240. Eleanor of Aquitaine (around 1122 to 1204) was queen of France and later of England and a powerful patron of culture. Christine de Pizan (1364 to around 1430) defended women in ''The Book of the City of Ladies,'' written in 1405."},{"heading":"Your turn","text":"1) Who wrote ''The Tale of Genji''? 2) Who was the only woman to rule China as emperor? 3) What did Hildegard of Bingen compose? 4) Which state did Razia Sultana rule? 5) Who was queen of both France and England? Answers: 1) Murasaki Shikibu. 2) Wu Zetian. 3) Music, along with writings on medicine and nature. 4) The Delhi Sultanate. 5) Eleanor of Aquitaine."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating the medieval period as the same length and shape everywhere. Mistake: assuming medieval women never held formal power or made lasting culture. Exit: (a) In what century did Murasaki Shikibu write? (b) Name a woman who ruled a medieval Muslim state. Answers: the early eleventh century; Razia Sultana of Delhi."}]}'::jsonb, '''Medieval'' usually means roughly 500 to 1500 CE, but the dates shift by region - use it with care outside Europe.', 13),
  (5, 'Rulers and leaders through history', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Recognize women who held and wielded sovereign power across different continents and eras. Warm-up: which ruling queens or empresses can you already name?"},{"heading":"The idea","text":"Some women did not merely influence power from beside the throne; they sat on it. Their reigns show that leadership was never beyond women, even where custom resisted it. Hatshepsut and Wu Zetian ruled ancient Egypt and China. In Europe, Elizabeth I of England and Catherine the Great of Russia presided over long and consequential reigns. In West Africa, Queen Nzinga of Ndongo and Matamba resisted Portuguese expansion and the slave trade for decades. In South Asia, Rani Lakshmibai of Jhansi became a leader of the 1857 revolt against British rule. These women governed, waged war, made law, and shaped the states they led. Studying them corrects the idea that rule was everywhere and always a man''s role, while also showing that a powerful woman at the top rarely changed the limits placed on women below her."},{"heading":"Key events & figures","text":"Elizabeth I reigned over England from 1558 to 1603. Catherine the Great ruled Russia from 1762 to 1796. Queen Nzinga (around 1583 to 1663) led Ndongo and Matamba, in present-day Angola, against Portuguese slavers. Rani Lakshmibai of Jhansi (around 1828 to 1858) died fighting in the Indian Rebellion of 1857. Isabella I of Castile (1451 to 1504) helped unify Spain. Amina of Zazzau is remembered as a warrior queen in what is now northern Nigeria. Earlier still, Theodora (around 500 to 548) wielded great influence as empress of the Byzantine Empire."},{"heading":"Your turn","text":"1) Who reigned over England from 1558 to 1603? 2) Which Russian ruler governed from 1762 to 1796? 3) Who resisted the Portuguese in present-day Angola? 4) Which Indian queen fought in the 1857 revolt? 5) Which queen helped unify Spain? Answers: 1) Elizabeth I. 2) Catherine the Great. 3) Queen Nzinga. 4) Rani Lakshmibai of Jhansi. 5) Isabella I of Castile."},{"heading":"Common mistakes & exit ticket","text":"Mistake: confusing a queen consort with a queen who rules in her own right. Mistake: assuming women rulers appear only in Europe. Exit: (a) Where did Queen Nzinga rule? (b) In what revolt did Rani Lakshmibai fight? Answers: Ndongo and Matamba, in present-day Angola; the Indian Rebellion of 1857."}]}'::jsonb, 'A regnant queen rules in her own right; a consort is married to a ruler - keep the two apart.', 13),
  (6, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"A central method of women''s history is to...","options":["rely only on official chronicles","read sources against the grain to recover hidden lives","study rulers alone","avoid letters and diaries as unreliable"],"answer":1,"explanation":"Historians read records against the grain and use letters, court cases, and oral history - see ''Why we study women''s history.''"},{"prompt":"Hatshepsut is best described as...","options":["a Greek poet","a pharaoh who ruled Egypt in her own right","a Byzantine empress","a medieval abbess"],"answer":1,"explanation":"Hatshepsut reigned as pharaoh around 1479 to 1458 BCE."},{"prompt":"Hypatia of Alexandria was known as a...","options":["suffragette","mathematician and philosopher","queen of Egypt","novelist"],"answer":1,"explanation":"She taught mathematics, astronomy, and philosophy before her death around 415 CE."},{"prompt":"''The Tale of Genji,'' often called the first novel, was written by...","options":["Christine de Pizan","Murasaki Shikibu","Ban Zhao","Hildegard of Bingen"],"answer":1,"explanation":"Murasaki Shikibu wrote it in early eleventh-century Japan."},{"prompt":"Razia Sultana ruled which medieval state?","options":["the Byzantine Empire","the Delhi Sultanate","the Kingdom of Castile","Han China"],"answer":1,"explanation":"She governed the Delhi Sultanate from 1236 to 1240."},{"prompt":"Queen Nzinga is remembered for resisting which European power?","options":["Britain","Portugal","Russia","France"],"answer":1,"explanation":"Nzinga led Ndongo and Matamba against Portuguese expansion and the slave trade."}]}'::jsonb, null, 8),
  (7, 'The long fight for education and work', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Trace how women won access to schooling, universities, and the professions, and see which barriers remained. Warm-up: before the 1800s, who was mostly kept out of universities?"},{"heading":"The idea","text":"For centuries, formal education and most paid professions were closed to women, who were taught that their proper place was the home. The nineteenth century began to crack that wall open. Campaigners argued that denying women learning wasted half of humanity''s talent. Colleges started to admit women, medical and law schools slowly followed, and the growth of factories and offices drew women into wage labor, though usually at lower pay and in narrower roles. Access came unevenly, shaped by class, race, and region: a wealthy woman might win a tutor or a college place while a working woman labored long hours for little. Even admission rarely meant equality, since many institutions let women attend yet withheld the full degree or the right to practice. Each gain was the fruit of long organizing rather than a gift freely given."},{"heading":"Key events & figures","text":"Oberlin College in the United States admitted women alongside men from 1837. Elizabeth Blackwell earned a medical degree in 1849, the first woman to do so in the United States. In England, Girton College, Cambridge, opened to women in 1869, though Cambridge withheld full degrees from women until 1948. The Married Women''s Property Acts of 1870 and 1882 let British wives own their own earnings and property. The 1911 Triangle Shirtwaist Factory fire in New York, which killed 146 workers, most of them young immigrant women, drove new safety and labor laws and strengthened women''s unions."},{"heading":"Your turn","text":"1) Which United States college admitted women from 1837? 2) Who earned the first United States medical degree given to a woman? 3) When did Girton College open? 4) What did the Married Women''s Property Acts allow? 5) What followed the Triangle fire? Answers: 1) Oberlin College. 2) Elizabeth Blackwell, in 1849. 3) 1869. 4) Wives to own their own earnings and property. 5) New workplace safety and labor reforms."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming that admission to a college meant equal treatment or a full degree. Mistake: forgetting that access varied sharply by class and race. Exit: (a) In what year did Elizabeth Blackwell qualify as a doctor? (b) Until what year did Cambridge withhold full degrees from women? Answers: 1849; 1948."}]}'::jsonb, '''Suffrage'' means the right to vote; this lesson covers the earlier and parallel fight for schooling and paid work.', 14),
  (8, 'The suffrage movements', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how the campaign for women''s voting rights unfolded in the United States, Britain, and around the world. Warm-up: which country do you think was first to give women the national vote?"},{"heading":"The idea","text":"The organized demand for women''s suffrage grew through the nineteenth century into a worldwide movement. In the United States it is often dated to the 1848 Seneca Falls Convention, where Elizabeth Cady Stanton''s Declaration of Sentiments called for the vote. Campaigners split over tactics: some pressed patiently through petitions and lobbying, while others, such as Britain''s militant suffragettes led by Emmeline Pankhurst, turned to protest, hunger strikes, and civil disobedience. Victory came country by country, frequently first to some women and only later to all. The struggle also exposed its own divisions, as Black and working-class women were often sidelined by movements led by wealthier white women, and in many places suffrage for women arrived alongside, or well after, broader fights over who counted as a full citizen."},{"heading":"Key events & figures","text":"New Zealand became the first self-governing country to grant women the national vote in 1893. The Seneca Falls Convention met in 1848. In Britain, the Representation of the People Act of 1918 enfranchised women over 30, and the 1928 act gave women the vote on equal terms with men at 21. The United States ratified the Nineteenth Amendment in 1920, though many Black women faced further barriers for decades. Switzerland granted women the federal vote only in 1971, and Saudi Arabia allowed women to vote in 2015, showing how long the global process ran."},{"heading":"Your turn","text":"1) Where and when was the Declaration of Sentiments issued? 2) Which country first gave women the national vote? 3) Who led Britain''s militant suffragettes? 4) What did the United States ratify in 1920? 5) When did Swiss women gain the federal vote? Answers: 1) Seneca Falls, in 1848. 2) New Zealand, in 1893. 3) Emmeline Pankhurst. 4) The Nineteenth Amendment. 5) 1971."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking one law gave all women the vote at once; many arrived in stages or excluded some women. Mistake: picturing a single, united movement rather than one divided by class and race. Exit: (a) In what year did New Zealand enfranchise women? (b) What did Britain''s 1928 act do? Answers: 1893; it gave women the vote on equal terms with men."}]}'::jsonb, 'Winning the vote (enfranchisement) often came in stages - partial first, then equal - so check the fine print of each date.', 14),
  (9, 'The waves of feminism and global women''s movements', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe the first, second, and third waves of feminism and the global women''s movements of the twentieth and twenty-first centuries. Warm-up: what rights do you think the earliest organized feminists focused on?"},{"heading":"The idea","text":"Historians often sort modern feminism into ''waves.'' The first wave, running through the nineteenth and early twentieth centuries, focused on legal rights, above all suffrage and the right to own property. The second wave, from the 1960s into the 1980s, widened the agenda to work, family, reproductive rights, and everyday inequality, captured in the slogan that the personal is political. The third wave, from the 1990s, stressed diversity, individual choice, and the insight that gender overlaps with race, class, and sexuality. Alongside these largely Western labels, women organized across Africa, Asia, and Latin America on their own terms, and the United Nations gave the cause a global stage. The wave model is useful but imperfect: the movements overlapped, disagreed, and looked very different outside Europe and North America."},{"heading":"Key events & figures","text":"Simone de Beauvoir published ''The Second Sex'' in 1949, and Betty Friedan''s ''The Feminine Mystique'' appeared in 1963, helping spark the second wave. Rebecca Walker popularized the phrase ''third wave'' in 1992. The first United Nations World Conference on Women met in Mexico City in 1975, the United Nations adopted the CEDAW treaty on women''s rights in 1979, and the 1995 Beijing conference produced a widely cited platform for action. The legal scholar Kimberle Crenshaw named ''intersectionality'' in 1989, giving a term to how overlapping identities shape experience."},{"heading":"Your turn","text":"1) What was the first wave''s central demand? 2) Who wrote ''The Feminine Mystique,'' and when? 3) Who popularized the phrase ''third wave''? 4) Where did the 1995 world conference meet? 5) Who coined ''intersectionality''? Answers: 1) Legal rights, especially suffrage. 2) Betty Friedan, in 1963. 3) Rebecca Walker, in 1992. 4) Beijing. 5) Kimberle Crenshaw."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating the waves as sharp, separate eras with no overlap. Mistake: assuming feminism was only a Western movement. Exit: (a) What treaty did the United Nations adopt in 1979? (b) What did the 1963 book help launch? Answers: CEDAW; the second wave of feminism."}]}'::jsonb, 'The ''waves'' are a rough shorthand for bursts of activism, not sharp dividing lines - treat them loosely.', 14),
  (10, 'Science, the arts, and the ongoing story of rights', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Recognize women''s achievements in science and the arts, the recognition long denied them, and the continuing push for rights and representation. Warm-up: can you name a scientific discovery a woman made but did not get full credit for?"},{"heading":"The idea","text":"Women have shaped science and the arts for centuries, often while being written out of the record. Marie Curie remains the only person to win Nobel Prizes in two different sciences. Ada Lovelace wrote what many consider the first computer program in the 1840s. Yet credit was frequently withheld: Rosalind Franklin''s images were central to uncovering the structure of DNA, and Lise Meitner was passed over for the Nobel awarded for nuclear fission. In the arts, Artemisia Gentileschi painted masterworks in the 1600s, and countless women wrote under their own or borrowed names. The pattern of crediting a woman''s work to a man is now called the Matilda effect. The story is not finished: the push for education, equal pay, leadership, and representation continues worldwide, reminding us that recovering the past and improving the present are part of the same effort."},{"heading":"Key events & figures","text":"Marie Curie won the Nobel Prize in Physics in 1903 and in Chemistry in 1911. Ada Lovelace (1815 to 1852) wrote her program notes in 1843. Rosalind Franklin''s key DNA image, known as Photo 51, dates to 1952. Dorothy Hodgkin won the Chemistry Nobel in 1964. Malala Yousafzai became the youngest Nobel Peace laureate in 2014, honored for defending girls'' education. The historian Margaret Rossiter named the Matilda effect in 1993, drawing on the earlier activist Matilda Joslyn Gage."},{"heading":"Your turn","text":"1) Who won Nobel Prizes in two different sciences? 2) Who is often called the first computer programmer? 3) Whose images helped reveal the structure of DNA? 4) Who became the youngest Nobel Peace laureate, in 2014? 5) What is the Matilda effect? Answers: 1) Marie Curie. 2) Ada Lovelace. 3) Rosalind Franklin. 4) Malala Yousafzai. 5) The crediting of a woman''s scientific work to a man."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming that few famous names means little women''s achievement; the records were often kept against them. Mistake: thinking the fight for rights and representation is finished. Exit: (a) In what two sciences did Marie Curie win Nobel Prizes? (b) Who named the Matilda effect? Answers: physics and chemistry; Margaret Rossiter."}]}'::jsonb, 'When a discovery is credited to the wrong person, name the pattern: the Matilda effect, the overlooking of women in science.', 14)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0005-0000-4000-8000-00000000001e' and l.position = v.pos
);
